function validate([m, n, k]) {
  if (m < 1 || m > 100000 || n < 1 || n > 100000) return 'm and n are between 1 and 10^5.';
  if (m * n < 2 || m * n > 100000) return 'The grid needs between 2 and 10^5 cells.';
  if (k < 2 || k > m * n) return 'k is between 2 and m * n.';
  return null;
}

