function distanceSum(m, n, k) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) {
        result = result * base % MOD;
      }
      base = base * base % MOD;
      exponent /= 2n;
    }
    return result;
  };
  const rows = BigInt(m);
  const cols = BigInt(n);
  const rowDistances = cols * cols * (rows - 1n) * rows * (rows + 1n) / 6n;
  const colDistances = rows * rows * (cols - 1n) * cols * (cols + 1n) / 6n;
  const pairDistances = (rowDistances + colDistances) % MOD;
  const others = m * n - 2;
  const extra = k - 2;
  let numerator = 1n;
  let denominator = 1n;
  for (let i = 1; i <= extra; i++) {
    numerator = numerator * BigInt(others - extra + i) % MOD;
    denominator = denominator * BigInt(i) % MOD;
  }
  const ways = numerator * power(denominator, MOD - 2n) % MOD;
  return Number(pairDistances * ways % MOD);
}

