function distanceSum(m, n, k) {
  // List every set of k cells and add the distances of all its pairs.
  const cells = [];
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) cells.push([r, c]);
  const chosen = [];
  let total = 0;
  const place = start => {
    if (chosen.length === k) {
      for (let i = 0; i < k; i++) for (let j = i + 1; j < k; j++) total += Math.abs(chosen[i][0] - chosen[j][0]) + Math.abs(chosen[i][1] - chosen[j][1]);
      return;
    }
    for (let next = start; next <= cells.length - (k - chosen.length); next++) {
      chosen.push(cells[next]);
      place(next + 1);
      chosen.pop();
    }
  };
  place(0);
  return total % 1000000007;
}

