function generate(rand, size) {
  const pick = count => Math.floor(rand() * count);
  if (size === 'large') {
    // Grids of close to 10^5 cells in several shapes, from a single row to a single column.
    const m = [1, 2, 3, 10, 99, 250, 316, 1000, 50000, 100000][pick(10)];
    const n = Math.max(m === 1 ? 2 : 1, Math.floor(100000 / m) - pick(3));
    const cells = m * n;
    return [m, n, [2, 3, cells, cells - 1, Math.floor(cells / 2), 2 + pick(cells - 1)][pick(6)]];
  }
  // Small grids keep the number of arrangements tiny so that listing them is instant.
  for (;;) {
    const m = 1 + pick(4), n = 1 + pick(4);
    if (m * n < 2 || m * n > 12) continue;
    return [m, n, 2 + pick(m * n - 1)];
  }
}
